'''
Handles the storage, encryption, and decryption of password entries.
'''
from cryptography.fernet import Fernet
import json
import os

class PasswordVault:
    def __init__(self, filename):
        self.filename = filename
        self.entries = {}
        self.key = None

    def create_master_key(self, password):
        # For simplicity, we are using a static key generation method.
        # In a real-world scenario, you would derive the key from the password.
        self.key = Fernet.generate_key()

    def encrypt_data(self, data):
        fernet = Fernet(self.key)
        return fernet.encrypt(data.encode())

    def decrypt_data(self, encrypted_data):
        fernet = Fernet(self.key)
        return fernet.decrypt(encrypted_data).decode()

    def load_vault(self):
        if os.path.exists(self.filename):
            with open(self.filename, 'rb') as file:
                encrypted_data = file.read()
                decrypted_data = self.decrypt_data(encrypted_data)
                self.entries = json.loads(decrypted_data)

    def save_vault(self):
        with open(self.filename, 'wb') as file:
            data = json.dumps(self.entries)
            encrypted_data = self.encrypt_data(data)
            file.write(encrypted_data)

    def add_entry(self, service, username, password):
        self.entries[service] = {'username': username, 'password': password}
        self.save_vault()

    def get_entries(self):
        return self.entries
